-- =============================================================================
-- Institute Fee Manager — initial schema
--
-- Design notes
--   * Every "today" is computed in Asia/Kolkata via public.ist_today().
--   * Students carry a billing schedule (anchor date + cycle). Fee dues are
--     materialised rows in public.fee_dues, generated by
--     public._generate_student_dues() (on insert/update of a student and by the
--     daily cron). Anchoring every due to schedule_start_date + n * cycle avoids
--     month-end drift (31 Jan -> 28 Feb -> 31 Mar, not 28 Mar).
--   * Payments are allocated to dues (oldest first) through public.record_payment().
--     fee_dues.amount_paid is only ever written by security-definer functions.
--   * RLS: only users listed in public.admins can read/write anything. The
--     service role (used only by the cron job on the server) bypasses RLS.
--   * Daily reminders are de-duplicated with a unique (reminder_date, kind) row
--     claimed atomically by public.claim_daily_reminder().
-- =============================================================================

create extension if not exists pg_trgm with schema extensions;

-- -----------------------------------------------------------------------------
-- Types
-- -----------------------------------------------------------------------------
create type public.billing_cycle as enum ('monthly', 'quarterly', 'half_yearly', 'yearly', 'custom', 'one_time');
create type public.student_status as enum ('active', 'archived');
create type public.payment_method as enum ('cash', 'upi', 'card', 'bank_transfer', 'cheque', 'other');
create type public.due_source as enum ('auto', 'manual');

-- -----------------------------------------------------------------------------
-- Helpers
-- -----------------------------------------------------------------------------
create or replace function public.ist_today()
returns date
language sql
stable
set search_path = ''
as $$
  select (now() at time zone 'Asia/Kolkata')::date
$$;

create or replace function public.cycle_months(p_cycle public.billing_cycle, p_custom int)
returns int
language sql
immutable
set search_path = ''
as $$
  select case p_cycle
    when 'monthly' then 1
    when 'quarterly' then 3
    when 'half_yearly' then 6
    when 'yearly' then 12
    when 'custom' then p_custom
    else null -- one_time
  end
$$;

create or replace function public._cycle_date(p_start date, p_months int, p_index int)
returns date
language sql
immutable
set search_path = ''
as $$
  select case
    when p_months is null then p_start
    else (p_start + make_interval(months => p_months * p_index))::date
  end
$$;

create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- -----------------------------------------------------------------------------
-- Admins
-- -----------------------------------------------------------------------------
create table public.admins (
  user_id uuid primary key references auth.users (id) on delete cascade,
  full_name text,
  created_at timestamptz not null default now()
);

create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.admins a where a.user_id = (select auth.uid()))
$$;

create or replace function public.is_service_role()
returns boolean
language sql
stable
set search_path = ''
as $$
  select coalesce((select auth.jwt()) ->> 'role', '') = 'service_role'
$$;

create or replace function public.can_manage()
returns boolean
language sql
stable
set search_path = ''
as $$
  select public.is_service_role() or public.is_admin()
$$;

-- -----------------------------------------------------------------------------
-- Students
-- -----------------------------------------------------------------------------
create table public.students (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  phone text not null,
  email text,
  guardian_name text,
  course text not null,
  admission_date date not null,
  fee_amount numeric(12, 2) not null,
  billing_cycle public.billing_cycle not null default 'monthly',
  cycle_interval_months int,
  -- First (or, after a reschedule, next) due date. All auto dues are anchored here.
  schedule_start_date date not null,
  end_date date,
  cycles_generated int not null default 0,
  status public.student_status not null default 'active',
  notes text,
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint students_name_len check (char_length(btrim(name)) between 1 and 120),
  constraint students_phone_fmt check (phone ~ '^\+?[0-9]{10,15}$'),
  constraint students_email_fmt check (email is null or email ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'),
  constraint students_guardian_len check (guardian_name is null or char_length(guardian_name) <= 120),
  constraint students_course_len check (char_length(btrim(course)) between 1 and 80),
  constraint students_fee_range check (fee_amount > 0 and fee_amount < 10000000),
  constraint students_custom_interval check (
    (billing_cycle = 'custom' and cycle_interval_months between 1 and 36)
    or (billing_cycle <> 'custom' and cycle_interval_months is null)
  ),
  constraint students_end_after_start check (end_date is null or end_date >= schedule_start_date),
  constraint students_notes_len check (notes is null or char_length(notes) <= 2000)
);

create index students_status_idx on public.students (status);
create index students_course_idx on public.students (course);
create index students_name_trgm_idx on public.students using gin (name extensions.gin_trgm_ops);
create index students_phone_idx on public.students (phone);

-- -----------------------------------------------------------------------------
-- Fee dues
-- -----------------------------------------------------------------------------
create table public.fee_dues (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.students (id) on delete cascade,
  due_date date not null,
  amount numeric(12, 2) not null,
  amount_paid numeric(12, 2) not null default 0,
  balance numeric(12, 2) generated always as (amount - amount_paid) stored,
  source public.due_source not null default 'manual',
  cycle_index int,
  description text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint fee_dues_amount_range check (amount > 0 and amount < 10000000),
  constraint fee_dues_paid_range check (amount_paid >= 0 and amount_paid <= amount),
  constraint fee_dues_description_len check (description is null or char_length(description) <= 200)
);

create unique index fee_dues_auto_unique on public.fee_dues (student_id, due_date) where source = 'auto';
create index fee_dues_student_idx on public.fee_dues (student_id, due_date);
create index fee_dues_open_idx on public.fee_dues (due_date) where amount_paid < amount;

-- -----------------------------------------------------------------------------
-- Payments
-- -----------------------------------------------------------------------------
create sequence public.receipt_number_seq;

create or replace function public.next_receipt_no()
returns text
language sql
volatile
set search_path = ''
as $$
  select 'RCP-' || to_char(public.ist_today(), 'YYYYMM') || '-'
    || lpad(nextval('public.receipt_number_seq')::text, 6, '0')
$$;

create table public.payments (
  id uuid primary key default gen_random_uuid(),
  receipt_no text not null unique default public.next_receipt_no(),
  student_id uuid not null references public.students (id) on delete restrict,
  amount numeric(12, 2) not null,
  paid_on date not null default public.ist_today(),
  method public.payment_method not null default 'cash',
  reference text,
  notes text,
  recorded_by uuid references auth.users (id) on delete set null,
  voided_at timestamptz,
  void_reason text,
  voided_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default now(),
  constraint payments_amount_range check (amount > 0 and amount < 10000000),
  constraint payments_reference_len check (reference is null or char_length(reference) <= 100),
  constraint payments_notes_len check (notes is null or char_length(notes) <= 1000),
  constraint payments_void_reason check (voided_at is null or char_length(btrim(coalesce(void_reason, ''))) > 0)
);

create index payments_student_idx on public.payments (student_id, paid_on desc);
create index payments_paid_on_idx on public.payments (paid_on) where voided_at is null;

create table public.payment_allocations (
  payment_id uuid not null references public.payments (id) on delete cascade,
  due_id uuid not null references public.fee_dues (id) on delete restrict,
  amount numeric(12, 2) not null check (amount > 0),
  primary key (payment_id, due_id)
);

create index payment_allocations_due_idx on public.payment_allocations (due_id);

-- -----------------------------------------------------------------------------
-- Reminder log (one row per day per kind => no duplicate reminders)
-- -----------------------------------------------------------------------------
create table public.reminder_logs (
  id uuid primary key default gen_random_uuid(),
  reminder_date date not null,
  kind text not null default 'daily_digest',
  status text not null default 'sending' check (status in ('sending', 'sent', 'failed')),
  triggered_by text not null default 'cron' check (triggered_by in ('cron', 'manual')),
  attempts int not null default 1,
  due_today_count int,
  overdue_count int,
  total_expected numeric(14, 2),
  message text,
  error text,
  sent_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (reminder_date, kind)
);

-- -----------------------------------------------------------------------------
-- Due generation
-- -----------------------------------------------------------------------------
create or replace function public._due_label(p_cycle public.billing_cycle, p_months int, p_date date)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when p_months is null then 'One-time fee'
    when p_months = 1 then 'Monthly fee - ' || to_char(p_date, 'Mon YYYY')
    else initcap(replace(p_cycle::text, '_', '-')) || ' fee - '
      || to_char(p_date, 'DD Mon YYYY') || ' to '
      || to_char((p_date + make_interval(months => p_months) - interval '1 day')::date, 'DD Mon YYYY')
  end
$$;

-- Generates auto dues for one student.
--   p_horizon   : generate every due on or before this date, and always make
--                 sure one future unpaid due exists (for "upcoming" views).
--   p_force_one : ignore the horizon and generate exactly one more due (used to
--                 absorb advance payments).
-- Returns the number of dues inserted. Internal: not executable by clients.
create or replace function public._generate_student_dues(
  p_student_id uuid,
  p_horizon date,
  p_force_one boolean default false
)
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  s public.students%rowtype;
  v_months int;
  v_idx int;
  v_date date;
  v_rows int;
  v_count int := 0;
  v_guard int := 0;
  v_today date := public.ist_today();
begin
  select * into s from public.students where id = p_student_id for update;
  if not found or s.status <> 'active' then
    return 0;
  end if;

  v_months := public.cycle_months(s.billing_cycle, s.cycle_interval_months);
  v_idx := s.cycles_generated;

  loop
    v_guard := v_guard + 1;
    exit when v_guard > 600;
    exit when v_months is null and v_idx >= 1;

    v_date := public._cycle_date(s.schedule_start_date, v_months, v_idx);
    exit when s.end_date is not null and v_date > s.end_date;

    if p_force_one then
      exit when v_count >= 1;
    else
      exit when v_date > p_horizon and exists (
        select 1 from public.fee_dues f
        where f.student_id = s.id and f.due_date > v_today and f.amount_paid < f.amount
      );
    end if;

    insert into public.fee_dues (student_id, due_date, amount, source, cycle_index, description)
    values (s.id, v_date, s.fee_amount, 'auto', v_idx, public._due_label(s.billing_cycle, v_months, v_date))
    on conflict (student_id, due_date) where source = 'auto' do nothing;

    get diagnostics v_rows = row_count;
    v_count := v_count + v_rows;
    v_idx := v_idx + 1;
  end loop;

  if v_idx <> s.cycles_generated then
    update public.students set cycles_generated = v_idx where id = s.id;
  end if;

  return v_count;
end;
$$;

-- Public entry point used by the daily cron (service role) or an admin.
create or replace function public.generate_all_dues(p_horizon_days int default 45)
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare
  r record;
  v_total int := 0;
  v_horizon date := public.ist_today() + greatest(0, least(coalesce(p_horizon_days, 45), 400));
begin
  if not public.can_manage() then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  for r in select id from public.students where status = 'active' loop
    v_total := v_total + public._generate_student_dues(r.id, v_horizon);
  end loop;

  return v_total;
end;
$$;

-- -----------------------------------------------------------------------------
-- Student triggers: normalise input, reschedule, archive / unarchive
-- -----------------------------------------------------------------------------
create or replace function public._students_before_write()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_months int;
  v_guard int := 0;
  v_schedule_changed boolean := false;
begin
  new.name := btrim(regexp_replace(new.name, '\s+', ' ', 'g'));
  new.course := btrim(regexp_replace(new.course, '\s+', ' ', 'g'));
  new.phone := regexp_replace(new.phone, '[\s()-]', '', 'g');
  new.email := nullif(lower(btrim(coalesce(new.email, ''))), '');
  new.guardian_name := nullif(btrim(coalesce(new.guardian_name, '')), '');
  new.notes := nullif(btrim(coalesce(new.notes, '')), '');

  if tg_op = 'INSERT' then
    new.cycles_generated := 0;
    new.archived_at := case when new.status = 'archived' then now() else null end;
    return new;
  end if;

  new.updated_at := now();

  v_schedule_changed :=
    new.fee_amount is distinct from old.fee_amount
    or new.billing_cycle is distinct from old.billing_cycle
    or new.cycle_interval_months is distinct from old.cycle_interval_months
    or new.schedule_start_date is distinct from old.schedule_start_date;

  if v_schedule_changed then
    new.cycles_generated := 0;
  end if;

  if new.status = 'archived' and old.status = 'active' then
    new.archived_at := now();
  elsif new.status = 'active' and old.status = 'archived' then
    new.archived_at := null;
    -- Resume billing from the next cycle on/after today rather than back-billing
    -- the archived period.
    if not v_schedule_changed then
      v_months := public.cycle_months(new.billing_cycle, new.cycle_interval_months);
      if v_months is not null then
        while public._cycle_date(new.schedule_start_date, v_months, new.cycles_generated) < public.ist_today()
          and v_guard < 600 loop
          new.cycles_generated := new.cycles_generated + 1;
          v_guard := v_guard + 1;
        end loop;
      end if;
    end if;
  end if;

  return new;
end;
$$;

-- After future dues are removed (archive, shortened end date), rewind the cycle
-- counter to just past the last remaining auto due of the current schedule, so
-- those cycles can be generated again if billing resumes or the end is extended.
create or replace function public._resync_cycle_counter(p_student_id uuid)
returns void
language sql
security definer
set search_path = ''
as $$
  update public.students s
  set cycles_generated = coalesce((
    select max(f.cycle_index) + 1 from public.fee_dues f
    where f.student_id = s.id and f.source = 'auto' and f.due_date >= s.schedule_start_date
  ), 0)
  where s.id = p_student_id
$$;

create or replace function public._students_after_write()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_horizon date := public.ist_today() + 45;
begin
  if tg_op = 'INSERT' then
    perform public._generate_student_dues(new.id, v_horizon);
    return null;
  end if;

  if new.status = 'archived' then
    if old.status = 'active' then
      -- Stop future billing: drop untouched future auto dues.
      delete from public.fee_dues
      where student_id = new.id and source = 'auto' and amount_paid = 0
        and due_date > public.ist_today();
      perform public._resync_cycle_counter(new.id);
    end if;
    return null;
  end if;

  if new.fee_amount is distinct from old.fee_amount
    or new.billing_cycle is distinct from old.billing_cycle
    or new.cycle_interval_months is distinct from old.cycle_interval_months
    or new.schedule_start_date is distinct from old.schedule_start_date then
    -- New schedule applies from schedule_start_date onwards. Untouched auto dues
    -- in that range are replaced; partly paid ones are kept.
    delete from public.fee_dues
    where student_id = new.id and source = 'auto' and amount_paid = 0
      and due_date >= new.schedule_start_date;
  end if;

  if new.end_date is not null and new.end_date is distinct from old.end_date then
    delete from public.fee_dues
    where student_id = new.id and source = 'auto' and amount_paid = 0
      and due_date > new.end_date;
    perform public._resync_cycle_counter(new.id);
  end if;

  perform public._generate_student_dues(new.id, v_horizon);
  return null;
end;
$$;

create trigger students_before_write
before insert or update on public.students
for each row execute function public._students_before_write();

create trigger students_after_insert
after insert on public.students
for each row execute function public._students_after_write();

create trigger students_after_update
after update of fee_amount, billing_cycle, cycle_interval_months, schedule_start_date, end_date, status
on public.students
for each row execute function public._students_after_write();

create trigger fee_dues_updated_at
before update on public.fee_dues
for each row execute function public.set_updated_at();

create trigger reminder_logs_updated_at
before update on public.reminder_logs
for each row execute function public.set_updated_at();

-- -----------------------------------------------------------------------------
-- Payments: record & void
-- -----------------------------------------------------------------------------
create or replace function public.record_payment(
  p_student_id uuid,
  p_amount numeric,
  p_paid_on date default null,
  p_method public.payment_method default 'cash',
  p_reference text default null,
  p_notes text default null,
  p_due_id uuid default null
)
returns public.payments
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_student public.students%rowtype;
  v_payment public.payments%rowtype;
  v_due public.fee_dues%rowtype;
  v_remaining numeric(12, 2);
  v_alloc numeric(12, 2);
  v_paid_on date := coalesce(p_paid_on, public.ist_today());
  v_guard int := 0;
begin
  if not public.can_manage() then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'Payment amount must be greater than zero' using errcode = '22023';
  end if;
  if round(p_amount, 2) <> p_amount then
    raise exception 'Payment amount can have at most 2 decimal places' using errcode = '22023';
  end if;
  if v_paid_on > public.ist_today() then
    raise exception 'Payment date cannot be in the future' using errcode = '22023';
  end if;

  select * into v_student from public.students where id = p_student_id for update;
  if not found then
    raise exception 'Student not found' using errcode = 'P0002';
  end if;

  insert into public.payments (student_id, amount, paid_on, method, reference, notes, recorded_by)
  values (
    p_student_id, p_amount, v_paid_on, coalesce(p_method, 'cash'),
    nullif(btrim(coalesce(p_reference, '')), ''),
    nullif(btrim(coalesce(p_notes, '')), ''),
    (select auth.uid())
  )
  returning * into v_payment;

  v_remaining := p_amount;

  if p_due_id is not null then
    select * into v_due from public.fee_dues
    where id = p_due_id and student_id = p_student_id
    for update;
    if not found then
      raise exception 'Selected due does not belong to this student' using errcode = '22023';
    end if;
    v_alloc := least(v_remaining, v_due.amount - v_due.amount_paid);
    if v_alloc > 0 then
      insert into public.payment_allocations (payment_id, due_id, amount) values (v_payment.id, v_due.id, v_alloc);
      update public.fee_dues set amount_paid = amount_paid + v_alloc where id = v_due.id;
      v_remaining := v_remaining - v_alloc;
    end if;
  end if;

  while v_remaining > 0 loop
    v_guard := v_guard + 1;
    if v_guard > 1000 then
      raise exception 'Payment allocation did not converge';
    end if;

    select * into v_due from public.fee_dues
    where student_id = p_student_id and amount_paid < amount
    order by due_date, created_at
    limit 1
    for update;

    if not found then
      -- Advance payment: bill the next cycle early and keep allocating.
      if public._generate_student_dues(p_student_id, null, true) = 0 then
        raise exception 'Payment exceeds the outstanding balance by %', v_remaining using errcode = '22023';
      end if;
      continue;
    end if;

    v_alloc := least(v_remaining, v_due.amount - v_due.amount_paid);
    insert into public.payment_allocations (payment_id, due_id, amount) values (v_payment.id, v_due.id, v_alloc);
    update public.fee_dues set amount_paid = amount_paid + v_alloc where id = v_due.id;
    v_remaining := v_remaining - v_alloc;
  end loop;

  return v_payment;
end;
$$;

create or replace function public.void_payment(p_payment_id uuid, p_reason text)
returns public.payments
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_payment public.payments%rowtype;
begin
  if not public.can_manage() then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) = 0 then
    raise exception 'A reason is required to void a payment' using errcode = '22023';
  end if;

  select * into v_payment from public.payments where id = p_payment_id for update;
  if not found then
    raise exception 'Payment not found' using errcode = 'P0002';
  end if;
  if v_payment.voided_at is not null then
    raise exception 'Payment is already voided' using errcode = '22023';
  end if;

  update public.fee_dues f
  set amount_paid = f.amount_paid - a.amount
  from public.payment_allocations a
  where a.payment_id = p_payment_id and a.due_id = f.id;

  delete from public.payment_allocations where payment_id = p_payment_id;

  update public.payments
  set voided_at = now(), void_reason = left(btrim(p_reason), 500), voided_by = (select auth.uid())
  where id = p_payment_id
  returning * into v_payment;

  return v_payment;
end;
$$;

-- -----------------------------------------------------------------------------
-- Reminders: atomic claim => at most one successful digest per day
-- -----------------------------------------------------------------------------
create or replace function public.claim_daily_reminder(
  p_date date,
  p_triggered_by text default 'cron',
  p_force boolean default false
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
begin
  if not public.can_manage() then
    raise exception 'Not authorized' using errcode = '42501';
  end if;

  insert into public.reminder_logs (reminder_date, kind, status, triggered_by)
  values (p_date, 'daily_digest', 'sending', coalesce(p_triggered_by, 'cron'))
  on conflict (reminder_date, kind) do update
    set status = 'sending',
        attempts = public.reminder_logs.attempts + 1,
        triggered_by = excluded.triggered_by,
        error = null
    where public.reminder_logs.status = 'failed' or p_force
  returning id into v_id;

  return v_id; -- null => already sent / in progress
end;
$$;

create or replace function public.finish_daily_reminder(
  p_id uuid,
  p_status text,
  p_due_today_count int default null,
  p_overdue_count int default null,
  p_total_expected numeric default null,
  p_message text default null,
  p_error text default null
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not public.can_manage() then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  if p_status not in ('sent', 'failed') then
    raise exception 'Invalid status' using errcode = '22023';
  end if;

  update public.reminder_logs
  set status = p_status,
      due_today_count = p_due_today_count,
      overdue_count = p_overdue_count,
      total_expected = p_total_expected,
      message = left(p_message, 20000),
      error = left(p_error, 2000),
      sent_at = case when p_status = 'sent' then now() else sent_at end
  where id = p_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- Views (security_invoker => caller's RLS applies)
-- -----------------------------------------------------------------------------
create view public.due_details
with (security_invoker = true) as
select
  f.id,
  f.student_id,
  f.due_date,
  f.amount,
  f.amount_paid,
  f.balance,
  f.source,
  f.description,
  f.created_at,
  s.name as student_name,
  s.phone as student_phone,
  s.course,
  s.status as student_status,
  case
    when f.balance = 0 then 'paid'
    when f.due_date < t.today then 'overdue'
    when f.due_date = t.today then 'due_today'
    else 'upcoming'
  end as due_status,
  greatest(0, t.today - f.due_date) as days_overdue
from public.fee_dues f
join public.students s on s.id = f.student_id
cross join (select public.ist_today() as today) t;

create view public.student_fee_summary
with (security_invoker = true) as
select
  s.id,
  s.name,
  s.phone,
  s.email,
  s.guardian_name,
  s.course,
  s.admission_date,
  s.fee_amount,
  s.billing_cycle,
  s.cycle_interval_months,
  s.schedule_start_date,
  s.end_date,
  s.status,
  s.notes,
  s.archived_at,
  s.created_at,
  s.updated_at,
  coalesce(d.total_billed, 0)::numeric(14, 2) as total_billed,
  coalesce(p.total_paid, 0)::numeric(14, 2) as total_paid,
  coalesce(d.pending_balance, 0)::numeric(14, 2) as pending_balance,
  coalesce(d.overdue_amount, 0)::numeric(14, 2) as overdue_amount,
  coalesce(d.due_today_amount, 0)::numeric(14, 2) as due_today_amount,
  coalesce(d.upcoming_amount, 0)::numeric(14, 2) as upcoming_amount,
  d.next_due_date,
  d.next_upcoming_date,
  p.last_payment_date,
  case
    when coalesce(d.overdue_amount, 0) > 0 then 'overdue'
    when coalesce(d.due_today_amount, 0) > 0 then 'due_today'
    else 'paid'
  end as payment_status
from public.students s
cross join (select public.ist_today() as today) t
left join lateral (
  select
    sum(f.amount) filter (where f.due_date <= t.today) as total_billed,
    sum(f.balance) filter (where f.due_date <= t.today) as pending_balance,
    sum(f.balance) filter (where f.due_date < t.today) as overdue_amount,
    sum(f.balance) filter (where f.due_date = t.today) as due_today_amount,
    sum(f.balance) filter (where f.due_date > t.today) as upcoming_amount,
    min(f.due_date) filter (where f.balance > 0) as next_due_date,
    min(f.due_date) filter (where f.balance > 0 and f.due_date >= t.today) as next_upcoming_date
  from public.fee_dues f
  where f.student_id = s.id
) d on true
left join lateral (
  select sum(pm.amount) as total_paid, max(pm.paid_on) as last_payment_date
  from public.payments pm
  where pm.student_id = s.id and pm.voided_at is null
) p on true;

-- Dashboard figures (active students only), all relative to IST today.
create or replace function public.dashboard_summary(p_upcoming_days int default 7)
returns table (
  total_students bigint,
  archived_students bigint,
  due_today_amount numeric,
  due_today_count bigint,
  overdue_amount numeric,
  overdue_students bigint,
  month_collection numeric,
  month_payments bigint,
  today_collection numeric,
  upcoming_amount numeric,
  upcoming_count bigint
)
language sql
stable
set search_path = ''
as $$
  with t as (
    select public.ist_today() as today,
           date_trunc('month', public.ist_today())::date as month_start,
           public.ist_today() + greatest(1, least(coalesce(p_upcoming_days, 7), 90)) as upcoming_end
  ),
  open_dues as (
    select f.* from public.fee_dues f
    join public.students s on s.id = f.student_id and s.status = 'active'
    where f.amount_paid < f.amount
  ),
  live_payments as (
    select pm.* from public.payments pm where pm.voided_at is null
  )
  select
    (select count(*) from public.students where status = 'active'),
    (select count(*) from public.students where status = 'archived'),
    (select coalesce(sum(balance), 0) from open_dues, t where due_date = t.today),
    (select count(*) from open_dues, t where due_date = t.today),
    (select coalesce(sum(balance), 0) from open_dues, t where due_date < t.today),
    (select count(distinct student_id) from open_dues, t where due_date < t.today),
    (select coalesce(sum(amount), 0) from live_payments, t where paid_on between t.month_start and t.today),
    (select count(*) from live_payments, t where paid_on between t.month_start and t.today),
    (select coalesce(sum(amount), 0) from live_payments, t where paid_on = t.today),
    (select coalesce(sum(balance), 0) from open_dues, t where due_date > t.today and due_date <= t.upcoming_end),
    (select count(*) from open_dues, t where due_date > t.today and due_date <= t.upcoming_end)
$$;

-- Distinct course list for filters.
create or replace function public.course_list()
returns setof text
language sql
stable
set search_path = ''
as $$
  select distinct course from public.students order by course
$$;

-- -----------------------------------------------------------------------------
-- Row Level Security
-- -----------------------------------------------------------------------------
alter table public.admins enable row level security;
alter table public.students enable row level security;
alter table public.fee_dues enable row level security;
alter table public.payments enable row level security;
alter table public.payment_allocations enable row level security;
alter table public.reminder_logs enable row level security;

create policy "admins read admins" on public.admins
  for select to authenticated using ((select public.is_admin()));

create policy "admins read students" on public.students
  for select to authenticated using ((select public.is_admin()));
create policy "admins insert students" on public.students
  for insert to authenticated with check ((select public.is_admin()));
create policy "admins update students" on public.students
  for update to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));

create policy "admins read dues" on public.fee_dues
  for select to authenticated using ((select public.is_admin()));
create policy "admins add manual dues" on public.fee_dues
  for insert to authenticated
  with check ((select public.is_admin()) and source = 'manual' and amount_paid = 0);
create policy "admins edit dues" on public.fee_dues
  for update to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));
create policy "admins delete unpaid dues" on public.fee_dues
  for delete to authenticated using ((select public.is_admin()) and amount_paid = 0);

create policy "admins read payments" on public.payments
  for select to authenticated using ((select public.is_admin()));
create policy "admins edit payment notes" on public.payments
  for update to authenticated using ((select public.is_admin())) with check ((select public.is_admin()));

create policy "admins read allocations" on public.payment_allocations
  for select to authenticated using ((select public.is_admin()));

create policy "admins read reminder logs" on public.reminder_logs
  for select to authenticated using ((select public.is_admin()));

-- -----------------------------------------------------------------------------
-- Privileges (Supabase grants broad defaults; tighten them)
-- -----------------------------------------------------------------------------
revoke all on table
  public.admins, public.students, public.fee_dues, public.payments,
  public.payment_allocations, public.reminder_logs,
  public.due_details, public.student_fee_summary
from anon, authenticated;
revoke all on sequence public.receipt_number_seq from anon, authenticated;

grant select on public.admins to authenticated;

grant select on public.students to authenticated;
grant insert (id, name, phone, email, guardian_name, course, admission_date, fee_amount, billing_cycle,
              cycle_interval_months, schedule_start_date, end_date, status, notes)
  on public.students to authenticated;
grant update (name, phone, email, guardian_name, course, admission_date, fee_amount, billing_cycle,
              cycle_interval_months, schedule_start_date, end_date, status, notes)
  on public.students to authenticated;

grant select, delete on public.fee_dues to authenticated;
grant insert (student_id, due_date, amount, description) on public.fee_dues to authenticated;
grant update (due_date, amount, description) on public.fee_dues to authenticated;

grant select on public.payments to authenticated;
grant update (reference, notes) on public.payments to authenticated;

grant select on public.payment_allocations to authenticated;
grant select on public.reminder_logs to authenticated;
grant select on public.due_details, public.student_fee_summary to authenticated;

grant all on table
  public.admins, public.students, public.fee_dues, public.payments,
  public.payment_allocations, public.reminder_logs,
  public.due_details, public.student_fee_summary
to service_role;
grant usage on sequence public.receipt_number_seq to service_role;

revoke execute on all functions in schema public from public, anon, authenticated;

-- Needed by views, RLS policies and defaults evaluated as the caller.
grant execute on function public.ist_today() to authenticated, service_role;
grant execute on function public.is_admin() to authenticated, service_role;
grant execute on function public.is_service_role() to authenticated, service_role;
grant execute on function public.can_manage() to authenticated, service_role;
grant execute on function public.cycle_months(public.billing_cycle, int) to authenticated, service_role;

-- Public API.
grant execute on function public.dashboard_summary(int) to authenticated, service_role;
grant execute on function public.course_list() to authenticated, service_role;
grant execute on function public.record_payment(uuid, numeric, date, public.payment_method, text, text, uuid) to authenticated, service_role;
grant execute on function public.void_payment(uuid, text) to authenticated, service_role;
grant execute on function public.generate_all_dues(int) to authenticated, service_role;
grant execute on function public.claim_daily_reminder(date, text, boolean) to authenticated, service_role;
grant execute on function public.finish_daily_reminder(uuid, text, int, int, numeric, text, text) to authenticated, service_role;
